diagnostic_evidence.quote:
For $0 < q \le 2$ and $M, N > 0$ and $\bsigma$ with $\norm{\bsigma^{-1}}{\ell_q(\NN)} \le N$, denote
\begin{equation*} \label{B_X^q(M,N)}
	B_{X,\bsigma}^q(M,N):= \brab{v \in H_{X,\bsigma}: \, \norm{v}{H_{X,\bsigma}} \le M}.
\end{equation*}

and the asymptotical equivalence
 	\begin{equation*} \label{rho_n<}
 		\ \le \sqrt{\frac{1}{m} \sum_{k \ge m} k^{-2/q}}
 	\ \asymp 	m^{-1/q}, \ \ m \in \NN.
 \end{equation*}

The points from Assumption~\ref{points}{\rm (iii)} fulfill with high probability
		\begin{equation}\nonumber
			sup_{v\in B_{X,\bsigma}} \norm{v - S_{c_2n}^X v}{L_2(U,X;\mu)}
			\ \le \sqrt{\frac{1}{n} \sum_{s \ge n} d_s^2}.
		\end{equation}

\varrho_n(B_{X,\bsigma}^q(M,N), L_2(\DDi,X;\mu))  
 		\ 	\ll \		sup_{v\in B_{X,\bsigma}^{q}(M,N)} \norm{v - S_{c_3n}^X v}{L_2(\DDi,X;\mu)}
 		\ \ll MN n^{-1/q}.
